export function loadNovaQuirks() { return loadJSON(QUIRKS_KEY, {}); }
export function saveNovaQuirks(q) { saveJSON(QUIRKS_KEY, q && typeof q === "object" ? q : {}); }

/* LearnView mounting IS a Nova tab visit (2026-10-15), and
   recording it here is what retires the sidebar discovery
   pop (src/NovaSidebarPop.jsx reads hasVisitedNova from the
   same quirks store). Pure: an already recorded visit returns
   the same object, so the caller can skip the save. */
export function recordNovaVisit(q) {
  const s = q && typeof q === "object" ? q : {};
  if (s.hasVisitedNova) return s;
  return { ...s, hasVisitedNova: true };
}

export function pickNovaLine(lines, seed) {
  if (!Array.isArray(lines) || !lines.length) return null;
  return lines[Math.abs(Math.floor(seed || 0)) % lines.length];
}

/* Speech carries no markup: the sheet renders a card's why
   through RichText (bold and italic markers), but her voice
   reads the plain words. parseRichText owns the marker
   grammar, so plain text for speech is its segments rejoined
   with the markers stripped and the spacing tidied. */
export function plainSpeechText(text) {
  if (typeof text !== "string" || !text) return "";
  return parseRichText(text).map((seg) => seg.text).join("").replace(/\s+/g, " ").trim();
}

function speechSentence(text) {
  const t = typeof text === "string" ? text.trim() : "";
  if (!t) return "";
  return /[.!?]$/.test(t) ? t : t + ".";
}

/* The correction half of her spoken feedback (2026-10-15,
   the owner: on a wrong answer she teaches what the right
   answer was). Assembled only from the card's own fields,
   never new authored content:
   - option cards (quiz, cloze, visual, true or false,
     predict): the correct option's text, which the Player
     hands in already resolved to the order on screen;
   - spot the error: the card's fix, the piece as it should
     read;
   - order and build: the card's items in their true order;
   - match: no correction exists to state. By the time the
     sheet lands every pair stands matched on the stage, and
     the pairs are the lesson; the why alone teaches there.
   A right answer needs no correction at all. */
export function feedbackCorrectionFor(card, { good = false, correctText = null } = {}) {
  if (good || !card) return null;
  if (card.kind === "spoterror" && card.fix) {
    return "It should say: " + speechSentence(plainSpeechText(card.fix));
  }
  if ((card.kind === "order" || card.kind === "build") && Array.isArray(card.items) && card.items.length) {
    return "The right order: " + card.items.map((item) => plainSpeechText(item)).join(", then ") + ".";
  }
  if ((card.kind === "quiz" || card.kind === "cloze" || card.kind === "visualq" || card.kind === "truefalse" || card.kind === "predict") && correctText) {
    return "The answer was: " + speechSentence(plainSpeechText(correctText));
  }
  return null;
}

/* Her full spoken teaching for one answered card: on a miss,
   the correction plainly stated, then the card's authored
   why in her voice (the why itself is never rewritten; it
   is the lesson's own explanation, spoken instead of only
   printed). On a right answer, the why alone. Null when the
   card carries nothing to teach. */
export function feedbackTeachLine(card, ctx = {}) {
  const why = plainSpeechText(card && card.why);
  const correction = feedbackCorrectionFor(card, ctx);
  if (correction && why) {
    /* No passage twice in one breath (2026-10-18, the quiz repeat
       defect): when the why already carries the correct passage,
       verbatim inside it or near word for word, the correction
       plus the why reads the same passage twice, which is exactly
       what her speech bubble did in the owner's photo. The why
       already states the answer and the reason together there, so
       she speaks it once and the separate correction stands down.
       When the two are genuinely different passages she still
       carries the correction briefly, then the reason. */
    const correctText = ctx && ctx.correctText ? plainSpeechText(ctx.correctText) : "";
    const correctionBody = correction.replace(/^(It should say:|The answer was:|The right order:)\s+/, "");
    if ((correctText && passagesRepeat(correctText, why)) || passagesRepeat(correctionBody, why)) return why;
    return correction + " " + why;
  }
  return correction || why || null;
}

/* Which of her hour sets applies, on the same hours the mood
   logic already uses: asleep hours are hers to be dry in, and
   the early morning is when she is briefly almost cheerful. */
export function hourLineSet(hour) {
  if (typeof hour !== "number") return null;
  if (hour >= 23 || hour < 5) return "late";
  if (hour >= 5 && hour < 9) return "morning";
  return null;
}

/* What she actually knows about this learner, computed from the
   profile and the builtin progress and nothing else: how long
   she has known them (the profile's first active day), the
   current streak, the path they are furthest into, and the
   subjects their own scores separate into strong and weak. The
   subject reading needs at least three finished lessons in each
   of two subjects and a real gap between them; anything thinner
   and she holds her tongue (memoryLineFor returns less). */
export function computeNovaMemory(profile, progress, now = Date.now()) {
  const p = profile && typeof profile === "object" ? profile : {};
  const prog = progress && typeof progress === "object" ? progress : { lessons: {} };
  const days = Array.isArray(p.days) ? p.days.filter((d) => typeof d === "string") : [];
  let daysKnown = 0;
  if (days.length) {
    const t0 = Date.parse(days.slice().sort()[0] + "T00:00:00");
    if (!Number.isNaN(t0)) daysKnown = Math.max(0, Math.floor((now - t0) / 86400000));
  }
  const streak = typeof p.streak === "number" ? p.streak : 0;
  let furthest = null;
  const byCategory = {};
  for (const path of [...LEARNING_PATHS, ...TOPIC_COURSES]) {
    const pp = pathProgress(path, prog);
    if (pp.done > 0 && !pp.complete && (!furthest || pp.pct > furthest.pct)) {
      furthest = { title: path.title, pct: pp.pct };
    }
    for (const l of flattenPathLessons(path)) {
      const rec = (prog.lessons || {})[l.id];
      if (rec && rec.done && typeof rec.best === "number") {
        const cat = path.category || "General";
        const slot = byCategory[cat] || (byCategory[cat] = { total: 0, n: 0 });
        slot.total += rec.best;
        slot.n += 1;
      }
    }
  }
  let subjects = null;
  const cats = Object.keys(byCategory).filter((c) => byCategory[c].n >= 3);
  if (cats.length >= 2) {
    const avgs = cats.map((c) => ({ category: c, avg: byCategory[c].total / byCategory[c].n }));
    avgs.sort((a, b) => b.avg - a.avg);
    const strong = avgs[0];
    const weak = avgs[avgs.length - 1];
    if (strong.avg >= 70 && weak.avg < 85 && strong.avg - weak.avg >= 10) {
      subjects = { strong: strong.category, weak: weak.category, strongAvg: Math.round(strong.avg), weakAvg: Math.round(weak.avg) };
    }
  }
  return { daysKnown, streak, furthest, subjects };
}

/* The memory line itself, strongest fact first. Thin data earns
   a shorter line or none at all; she never guesses. */
export function memoryLineFor(facts) {
  if (!facts) return null;
  if (facts.subjects) {
    return "Your " + facts.subjects.strong + " is solid. The " + facts.subjects.weak + " scores leak.";
  }
  if (facts.furthest && facts.furthest.pct >= 25) {
    return facts.furthest.pct + " percent into " + facts.furthest.title + ". Nothing else is close.";
  }
  if (facts.daysKnown >= 7 && facts.streak >= 2) {
    return "Day " + (facts.daysKnown + 1) + " of this. Streak " + facts.streak + ". I keep the tally.";
  }
  if (facts.streak >= 5) return facts.streak + " days in a row. Someone has to count. It is me.";
  return null;
}

export function loadNovaMemoryFacts() {
  try {
    const profile = loadJSON(PROFILE_KEY, null);
    const progress = loadJSON(BUILTIN_PROGRESS_KEY, null);
    if (!profile && !progress) return null;
    return computeNovaMemory(profile || cortexEmptyProfile(), progress || cortexEmptyBuiltinProgress());
  } catch { return null; }
}

/* Her opinions, attached to answer events. One opinion at a
   time, the strongest first (a perfect lesson, then a hard card
   answered well, then a genuinely fast clean answer, then the
   raised brow at a long easy streak), and every opinion carries
   its own cooldown in the quirks store so praise and needling
   both stay rare. Returns the line, the face the sheet should
   show, and the updated quirks; null when she has nothing to
   say, which is most of the time. */
export function opinionForEvent(evt, quirks, now) {
  const q = { ...(quirks && typeof quirks === "object" ? quirks : {}) };
  const e = evt || {};
  const due = (key, cd) => !(typeof q[key] === "number" && now - q[key] < cd);
  if (e.perfectLesson && due("opinionPerfectAt", QUIRK_PERFECT_COOLDOWN_MS)) {
    q.opinionPerfectAt = now;
    return { line: NOVA_OPINION_PERFECT_LINE, face: "pleased", quirks: q };
  }
  if (e.good && e.hard && due("opinionHardAt", QUIRK_HARD_COOLDOWN_MS)) {
    q.opinionHardAt = now;
    return { line: NOVA_OPINION_HARD_LINE, face: "explaining", quirks: q };
  }
  if (e.good && typeof e.ms === "number" && e.ms > 0 && e.ms <= QUIRK_FAST_MS && due("opinionFastAt", QUIRK_FAST_COOLDOWN_MS)) {
    q.opinionFastAt = now;
    return { line: NOVA_OPINION_FAST_LINE, face: "pleased", quirks: q };
  }
  if (e.good && (e.easyStreak || 0) >= QUIRK_EASY_STREAK && due("opinionBrowAt", QUIRK_BROW_COOLDOWN_MS)) {
    q.opinionBrowAt = now;
    return { line: NOVA_OPINION_BROW_LINE, face: "deadpan", quirks: q };
  }
  return null;
}

/* The poke ladder. Pokes inside a minute stack; a quiet minute
   resets her patience. One and two amuse her (pleased), three
   and four draw the deadpan, five turns her away: asleep,
   taps ignored for an hour. Every step serves a line from its
   own variant set; the per step serve counts persist in
   pokes.turns, across ladders and locks alike, so a step
   cycles through its variants instead of repeating itself.
   The escalation shape, the gap reset, and the hour lock are
   exactly what they were before the ladder widened
   (2026-10-15). Pure: the caller loads and saves the quirks
   store. */
export function pokeStep(quirks, now) {
  const q = { ...(quirks && typeof quirks === "object" ? quirks : {}) };
  const pokes = q.pokes && typeof q.pokes === "object" ? { ...q.pokes } : { count: 0, lastAt: 0, lockUntil: 0 };
  if (pokes.lockUntil && now < pokes.lockUntil) {
    return { face: "asleep", line: null, ignore: true, quirks: q };
  }
  const gap = now - (pokes.lastAt || 0);
  let count = gap > QUIRK_POKE_GAP_MS ? 0 : (pokes.count || 0);
  count += 1;
  pokes.count = count;
  pokes.lastAt = now;
  const turns = pokes.turns && typeof pokes.turns === "object" ? { ...pokes.turns } : {};
  const serve = (step, variants) => {
    const n = typeof turns[step] === "number" ? turns[step] : 0;
    turns[step] = n + 1;
    return variants[n % variants.length];
  };
  let face = "pleased";
  let line = null;
  if (count >= 5) {
    face = "asleep";
    line = serve(5, NOVA_POKE_STEP_FIVE);
    pokes.lockUntil = now + QUIRK_POKE_LOCK_MS;
    pokes.count = 0;
  } else if (count === 4) {
    face = "deadpan";
    line = serve(4, NOVA_POKE_STEP_FOUR);
  } else if (count === 3) {
    face = "deadpan";
    line = serve(3, NOVA_POKE_STEP_THREE);
  } else if (count === 2) {
    line = serve(2, NOVA_POKE_STEP_TWO);
  } else {
    line = serve(1, NOVA_POKE_STEP_ONE);
  }
  pokes.turns = turns;
  q.pokes = pokes;
  return { face, line, ignore: false, quirks: q };
}

/* The gag and the shelf, her two slowest voices. */
export function gagDue(quirks, now) {
  const at = quirks && typeof quirks.gagAt === "number" ? quirks.gagAt : 0;
  return now - at >= QUIRK_GAG_COOLDOWN_MS;
}

export function recordGag(quirks, now) {
  return { ...(quirks && typeof quirks === "object" ? quirks : {}), gagAt: now };
}

/* A new object on her shelf gets one comment, ever, the first
   time she is seen after it lands, and comments as a class rest
   a fortnight between landings. Space is her favorite category
   and earns the warmer line. Returns the updated quirks whether
   or not a line came out, so the seen mark always lands. */
export function shelfCommentFor(obj, quirks, now) {
  if (!obj || !obj.pathId) return null;
  const q = { ...(quirks && typeof quirks === "object" ? quirks : {}) };
  const seen = Array.isArray(q.shelfSeen) ? q.shelfSeen.slice() : [];
  if (seen.includes(obj.pathId)) return null;
  seen.push(obj.pathId);
  q.shelfSeen = seen;
  const at = typeof q.shelfAt === "number" ? q.shelfAt : 0;
  if (now - at < QUIRK_SHELF_COOLDOWN_MS) return { line: null, quirks: q };
  q.shelfAt = now;
  const favorite = obj.glyph === "planet" || obj.category === "Space and Physics";
  return { line: favorite ? NOVA_SHELF_FAVORITE_LINE : NOVA_SHELF_LINE, quirks: q };
}

/* The egg's line picker, shared by the egg and tested here:
   the gag first when it is due and the seed allows (it stays
   the rarest), then the hour sets, then a memory line when the
   facts carry one, then the plain egg set. A morning line that
   would repeat her last line is denied, in character. */
export function pickEggLine(opts, quirks, now) {
  const o = opts || {};
  const q = { ...(quirks && typeof quirks === "object" ? quirks : {}) };
  const seed = typeof o.seed === "number" ? o.seed : now;
  if (o.allowGag && gagDue(q, now) && seed % 4 === 0) {
    q.gagAt = now;
    const gag = pickNovaLine(NOVA_GAG_LINES, seed);
    q.lastEggLine = gag;
    return { line: gag, quirks: q };
  }
  const set = hourLineSet(typeof o.hour === "number" ? o.hour : 12);
  let line = null;
  if (set === "morning") {
    line = pickNovaLine(NOVA_MORNING_LINES, seed);
    if (line && q.lastEggLine === line) line = NOVA_MORNING_DENIAL;
  } else if (set === "late") {
    line = pickNovaLine(NOVA_LATE_LINES, seed);
  } else if (o.facts) {
    line = memoryLineFor(o.facts);
  }
  if (!line) line = pickNovaLine(NOVA_EGG_LINES, seed);
  q.lastEggLine = line;
  return { line, quirks: q };
}

/* ── wave 3 (2026-10-14): the Nova home discipline ─────────────────
   Warm cream is the learning surface: status cards, review rows,
   and the Player's answer cards sit on cream with near black
   text, on the site's dark ground, and muted gold is the only
   accent. These four constants are that surface, named once so
   the home, the bench, and the Player cannot drift apart. */
const CREAM = "#FDF3D7";
const CREAM_INK = "#1A1A1A";
const CREAM_FAINT = "#6E675C";
const CREAM_LINE = "rgba(26, 26, 26, 0.16)";
const CREAM_GOLD = "#F0E3C0";
const WRONG_LINE = "#A79E8D";

/* The last visit stamp lives in its own storage key, outside the
   profile and outside the export document, so the return greeting
   costs the learner record nothing: no new profile field, no new
   export section, nothing an import has to validate. */
const LAST_VISIT_KEY = "cerebrum-learn2-lastvisit";

export function visitGapDays(lastVisitMs, nowMs) {
  if (!lastVisitMs || !Number.isFinite(lastVisitMs)) return 0;
  const startOfDay = (ms) => { const d = new Date(ms); d.setHours(0, 0, 0, 0); return d.getTime(); };
  return Math.max(0, Math.round((startOfDay(nowMs) - startOfDay(lastVisitMs)) / DAY_MS));
}

/* ── Nova's shelf ──────────────────────────────────────────────────
   One object per completed authored path, drawn as a small flat
   mark in the house style: warm ink line, one gold part. The set
   is derived from progress the learner already has; the shelf
   itself stores nothing. Path glyphs win over category glyphs,
   so The Human Body leaves a heart and the science path leaves
   its flask whatever shelf they share. */
const SHELF_GLYPH_BY_PATH = {
  "how-science-works": "flask",
  "space-and-the-solar-system": "planet",
  "matter-and-energy": "atom",
};
const SHELF_GLYPH_BY_CATEGORY = {
  "Mind and Brain": "mind",
  "Body and Health": "heart",
  "Life and Evolution": "leaf",
  "Earth and Climate": "cloud",
  "Space and Physics": "prism",
  "Matter and Energy": "atom",
};

export function shelfGlyphFor(path) {
  if (!path) return "spark";
  return SHELF_GLYPH_BY_PATH[path.id] || SHELF_GLYPH_BY_CATEGORY[path.category] || "spark";
}

export function shelfObjects(paths, progress) {
  return (paths || [])
    .filter((p) => pathProgress(p, progress).complete)
    .map((p) => ({ pathId: p.id, title: p.title, glyph: shelfGlyphFor(p) }));
}

